import{z as s,x as B,o as i,c as d,q as E,j as r,D as n,d as e,s as o,S as p,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"互连半节距与金属层","description":"","frontmatter":{"title":"互连半节距与金属层","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/interconnect-halfpitch.md","filePath":"litho/interconnect-halfpitch.md","lastUpdated":1791413859000}'),h={name:"litho/interconnect-halfpitch.md"};function m(A,a,c,f,D,u){const l=B("Mermaid");return i(),d("div",null,[a[2]||(a[2]=E('<h1 id="互连半节距与金属层" tabindex="-1">互连半节距与金属层 <a class="header-anchor" href="#互连半节距与金属层" aria-label="Permalink to &quot;互连半节距与金属层&quot;">​</a></h1><div class="epigraph"><p>晶体管之上是多层金属互连；半节距描述相邻线中心距的一半。节点推进时，互连缩放往往比栅长更早碰到图形化极限。</p><footer>—— 据 Sze 器件互连讨论与 Mack, Fundamental Principles of Optical Lithography 对节距作为光刻对象的整理</footer></div><p><a href="/litho/cmos-inverter-pair">上一课</a>说明前道需要 n/p 分区与多块掩模。<a href="/litho/mosfet-gate-length">MOSFET 与栅长</a> 不是芯片上唯一的横向尺度。缺口：金属线宽与节距如何命名、为何与栅长并列成为节点指标，以及为何每一层金属都要再做一次图形。晶体管做成之后，电路仍不存在，直到金属被画在指定网上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逻辑门必须接到电源与相邻单元。铝或铜互连层 M1、M2… 各由图形定义沟槽或线条。线越密，电阻电容延迟越大；继续缩小就要更细的线、更薄的介质。若只谈栅长，无法理解规格书里「金属节距 40 nm」与栅长并排出现。缺口是后道的尺度语言：半节距，以及多层金属每一层都是一次图形化。</p><h3 id="半节距不是线宽的别名" tabindex="-1">半节距不是线宽的别名 <a class="header-anchor" href="#半节距不是线宽的别名" aria-label="Permalink to &quot;半节距不是线宽的别名&quot;">​</a></h3><p>线宽 \\(W\\) 与间距 \\(S\\) 可以不相等。节距 \\(p=W+S\\)，半节距 \\(p/2\\)。只有 1:1 线空时半节距才等于线宽。把「半节距 20 nm」读成「线宽一定是 20 nm」，设计规则与光刻目标都会偏。DRAM 常用阵列半节距对外说话；逻辑常用接触多晶节距与金属节距的组合。</p><p><span class="marginnote">代个数字：节距 40 nm 若 1:1 线空，则线宽 = 间距 = 20 nm，半节距 = 20 nm，两者恰好相等；若改成线宽 12 nm、间距 28 nm，节距仍是 40 nm、半节距仍是 20 nm，但线宽完全不是 20 nm——这就是半节距不能当线宽别名读的原因。</span></p><p><span class="marginnote">M1 通常最密，上层可逐层放宽以降低电阻。通孔连接相邻金属层，图形是孔而不是线，后课专讲。本课先把线的节距钉死。</span></p><p><span class="marginnote">直觉类比：金属互连栈像城市道路网——M1 是最窄最密的巷子，直接通到每家门口（晶体管）；越往上越是宽阔的高架路，负责长距离运输。巷子不敢修宽（占地），高架不敢修窄（电阻发热），所以上层金属故意放宽、走大电流。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>后道典型顺序：介质沉积 → 图形化开槽 → 阻挡层与种子 → 铜填充 → 化学机械抛光。每一金属层有最小 \\(W\\) 与最小 \\(S\\)，半节距 \\(\\approx p/2\\)。图形化的对象是整层导线图案：哪里有金属、哪里是绝缘。没有这一层图形，晶体管即使做成也无法构成电路。</p><p>半节距成为对外规格，是因为它同时约束线宽与间距：只缩 \\(W\\) 而 \\(S\\) 不缩，电容仍在；只缩 \\(S\\) 则桥连风险先爆。路线图表格因此报 pitch 而不是只报 CD。本课要的正是这把尺子，好让后课「一次曝光够不够」问的是 \\(p\\)，不是某个营销纳米数。</p><p>节点路线图在栅长缩小放缓之后，把金属节距与接触多晶节距推到台前。后课 <a href="/litho/node-vs-gate-length">节点名不再等于栅长</a> 会说明对外数字与这些物理节距如何脱钩；本课先给出物理量本身。</p><p><span class="marginnote">接触多晶节距（CPP）是栅方向上相邻接触栅的重复周期，常与金属一节距一起出现在逻辑节点表里。它不是 \\(L\\)，而是另一把前道尺子。</span></p>',15)),(i(),r(p,null,{default:n(()=>[o(l,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20FEOL%5B%22%E5%89%8D%E9%81%93%E6%A0%85%E4%B8%8E%E6%9C%89%E6%BA%90%22%5D%20--%3E%20M1%5B%22%E7%AC%AC%E4%B8%80%E5%B1%82%E9%87%91%E5%B1%9E%E5%9B%BE%E5%BD%A2%22%5D%0A%20%20M1%20--%3E%20VIA%5B%22%E9%80%9A%E5%AD%94%22%5D%0A%20%20VIA%20--%3E%20M2%5B%22%E6%9B%B4%E9%AB%98%E9%87%91%E5%B1%9E%E5%B1%82%22%5D%0A%20%20M1%20--%3E%20HP%5B%22%E5%8D%8A%E8%8A%82%E8%B7%9D%E8%A7%84%E6%A0%BC%22%5D%0A%20%20M2%20--%3E%20RC%5B%22%E4%BA%92%E8%BF%9E%20RC%20%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[e("互连图形化与前道用同一类图形转移思想：先定义平面图案，再把材料填进或蚀刻掉。动机同样根本：没有图案，铜无法出现在指定的网表位置。节距变小之后，单次曝光是否够用，是 "),t("a",{href:"/litho/single-expose-limit"},"多重图形化之前的单次曝光极限"),e(" 的题目；本课不把波长与孔径提前解完，只指出对象是节距而不仅仅是栅长。")],-1)),a[5]||(a[5]=t("p",null,"层间介质变薄、线距变近，电容上升；线截面积下降，电阻上升。电路于是要求更多层金属来换布线资源，而不是无限缩小同一层的节距。图形化层数因此随节点增加：每一层都是一次图案定义。这与前道「栅只有一层」不同——互连是栈，节距可以每层不同，最密的通常靠近晶体管。",-1)),(i(),r(p,null,{default:n(()=>[o(l,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%8A%82%E8%B7%9D%20p%20%E7%BC%A9%E5%B0%8F%22%5D%20--%3E%20WR%5B%22%E7%BA%BF%E6%88%AA%E9%9D%A2%20%E2%86%93%20%E2%86%92%20%E7%94%B5%E9%98%BB%20R%20%E2%86%91%22%5D%0A%20%20P%20--%3E%20SP%5B%22%E7%BA%BF%E9%97%B4%E8%B7%9D%20%E2%86%93%20%E2%86%92%20%E7%94%B5%E5%AE%B9%20C%20%E2%86%91%22%5D%0A%20%20WR%20--%3E%20RC%5B%22RC%20%E5%BB%B6%E8%BF%9F%20%E2%86%91%22%5D%0A%20%20SP%20--%3E%20RC%0A%20%20RC%20--%3E%20MORE%5B%22%E5%8A%A0%E9%87%91%E5%B1%9E%E5%B1%82%E6%8D%A2%E5%B8%83%E7%BA%BF%E8%B5%84%E6%BA%90%22%5D%0A%20%20MORE%20--%3E%20LAY%5B%22%E5%9B%BE%E5%BD%A2%E5%8C%96%E5%B1%82%E6%95%B0%E9%9A%8F%E8%8A%82%E7%82%B9%E5%A2%9E%E5%8A%A0%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p>这张图回答的问题是：为什么节距缩下去之后，产业答案是「加层」而不是「继续缩」——RC 两支同时恶化，缩小本身在惩罚自己。</p><p><span class="marginnote">为什么 RC 这条腿要紧：晶体管开关得再快，信号在导线里过不去也是白搭。互连 RC 延迟不控制，芯片的时钟频率会被「电线」而不是「开关」拖住——这正是后道金属节距和栅长一样是硬指标、要写进节点规格的原因。</span></p><p>RC 延迟随线变细、介质变近而变差，这是「为何还要继续做更密图形」的电路理由。光刻要服务的是这张网，不是某一根栅的美学。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开双镶嵌步骤、低介电常数材料化学或背面供电。不写照明、胶与成像公式。通孔与接触孔的孔类图形后课才与线对照。</p><p>双重图形化出现之后，同一金属层可能被拆成两次线图形，节距定义仍是最终铜线的 \\(p\\)，不是单次曝光的节距。本课尺子是成品节距。后课默认：后道有多层金属；每层有节距；半节距是 \\(p/2\\)，仅在 1:1 时等于线宽。下一课解释节点名为什么不再等于 \\(L\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>后道金属层各需一次图形化；半节距是 \\(p/2\\)，不等于任意线宽。</li><li>节点规格越来越看金属节距与接触多晶节距，而不只看栅长。</li><li>图形化动机：把网表上的导线写在指定位置。</li><li>单次曝光够不够，后课再谈；本课只定义对象。</li><li>1:1 线空时半节距才等于线宽；否则必须同时报 \\(W\\) 与 \\(S\\)。</li><li>出处：Sze &amp; Ng, <em>Physics of Semiconductor Devices</em>；Mack, <em>Fundamental Principles of Optical Lithography</em>。</li></ul>',8))])}const P=s(h,[["render",m]]);export{_ as __pageData,P as default};
